"""Build a public evidence page from the current campaign application record."""
from pathlib import Path
import html,json
from site_shell import apply_shell
root=Path(__file__).resolve().parents[1]
d=json.loads((root/'docs/data/trump/reference-run.json').read_text(encoding='utf-8'))
if d.get('schema_version')!=2:raise ValueError('Publish a campaign application record first.')
esc=html.escape;fmt=lambda n:f'{n:,}'
params=d['parameters']
topics=''.join(f'<tr><td>{t["id"]}</td><td>{esc(t.get("naming",{}).get("modal_label",", ".join(t["words"][:5])))}</td><td>{fmt(t["count"])}</td></tr>' for t in d['topics'])
status='The classifier has passed independent evaluation and actual human acceptance.' if d['classifier_validated'] else ('Campaign discovery, naming and two-human synthesis are complete. Independent annotations and classifier validation must finish before presidential prevalence is reported.' if d['human_review_performed'] else 'Campaign discovery is complete. Human theme synthesis and independent classifier validation must finish before presidential prevalence is reported.')
development=''
if d.get('development'):
    dev=d['development'];scores=dev['scores'];human=dev['independent_human_agreement']
    if not d['classifier_validated']:status='Development is complete; the held-out sample remains unopened. The first comparison identifies measurement boundaries that need review before any proposed refinement or independent evaluation. No presidential prevalence is reported.'
    results=''.join(f'<tr><td>{"OpenAI GPT-4o" if name=="llm" else "Boolean dictionary"}</td><td>{100*score["agreement"]:.0f}%</td><td>{score["cohens_kappa"]:.4f}</td></tr>' for name,score in scores.items())
    development=f'''<h2>Development makes the measurement testable.</h2><p>Two independent human coding passes covered {dev['n']} presidential posts, agreeing on {human['agreement']:.0%} before adjudication resolved {dev['adjudicated_disagreements']} differences (Cohen’s κ = {human['cohens_kappa']:.3f}). Both original answers and the adjudication remain in the record.</p><div class="tutorial-table"><table><caption>First development comparison against human consensus. This is classifier selection, not independent validation.</caption><thead><tr><th>Candidate</th><th>Development agreement</th><th>Cohen’s κ</th></tr></thead><tbody>{results}</tbody></table></div><p>The higher-agreement rule selected the LLM. Its result is below the eventual &gt;85% evaluation requirement. The model used the residual more often than the reviewers, and missed all seven consumer-relations reference labels. These differences make the next research task concrete: review the written definitions and their application while preserving the unopened 250-post evaluation sample.</p><p><a href="../data/trump/campaign/development_report.json">Metrics and confusion counts</a> · Original labels and adjudication (retained privately) · Retained model responses (retained privately) · <a href="../data/trump/campaign/classifier_selection.json">Frozen classifier specification</a></p>'''
if d.get('evaluation_proceed_decision') and not d['classifier_validated']:
    status='The principal investigator retained the current codebook and classifier for this methodological demonstration. The original 250-post packet has been released for independent human annotation. Held-out performance and presidential prevalence are not yet available.'
    development=development.replace('These differences make the next research task concrete: review the written definitions and their application while preserving the unopened 250-post evaluation sample.','The researcher chose to evaluate this unchanged specification as a methodological demonstration. The next task is independent annotation of the original 250-post evaluation sample; observed performance will be reported with its limitations.')
    development+='<p><a href="../data/trump/campaign/evaluation_proceed_decision.json">Recorded decision to proceed with the unchanged codebook</a></p>'
evaluation=''
if d.get('evaluation_completed'):
    development=development.replace('The next task is independent annotation of the original 250-post evaluation sample; observed performance will be reported with its limitations.','The original 250-post evaluation sample was subsequently annotated and evaluated without changing that specification; its results appear below.')
    ev=d['validation'];m=ev['metrics'];human=ev['independent_human_agreement'];lo,hi=m['agreement_wilson_95']
    status=('Independent evaluation is complete and the declared criteria passed; actual human acceptance is still required.' if ev['gate_passed'] else 'Independent evaluation is complete. The classifier did not meet the declared acceptance criteria; full-corpus classification has not run.') if not d['classifier_validated'] else status
    development=development.replace('The next task is independent annotation of the original 250-post evaluation sample; observed performance will be reported with its limitations.','The separate evaluation below tests that unchanged specification.')
    pct=lambda x:'Not estimable' if x is None else f'{x:.1%}'
    theme_rows=''.join(f'<tr><td>{esc(name)}</td><td data-label="Support">{v["human_n"]}</td><td data-label="Precision">{pct(v["precision"])}</td><td data-label="Recall">{pct(v["recall"])}</td></tr>' for name,v in m['per_label'].items())
    evaluation=f'''<h2>Held-out evaluation: what transfers, and what does not.</h2><p>Two independent human coding passes covered the reserved {ev['n_benchmark']} presidential posts; all {ev['adjudicated_disagreements']} differences were then adjudicated. Initial human agreement was {human['agreement']:.0%} (κ = {human['cohens_kappa']:.3f}). The frozen classifier was evaluated against their final consensus, without changing its codebook or prompt.</p><div class="tutorial-metrics"><div class="tutorial-metric"><strong>{m['agreement']:.0%}</strong><span>classifier agreement with consensus</span></div><div class="tutorial-metric"><strong>{lo:.1%}–{hi:.1%}</strong><span>95% Wilson interval</span></div><div class="tutorial-metric"><strong>{m['cohens_kappa']:.3f}</strong><span>Cohen’s κ against consensus</span></div></div><p>The classifier matched 175 of 250 labels. It assigned the residual to 86 posts, compared with 41 in human consensus. Of its 75 disagreements, 45 involved a substantive human theme classified as residual. The model detected 62 of 83 political-opponent posts and 25 of 32 gratitude posts, but missed all three consumer-relations instances and the single golf-resort instance. Merchandise had no reference instances, so its recall cannot be estimated from this sample.</p><div class="tutorial-table"><table class="evaluation-table"><caption>Held-out performance by theme. Support is the number of consensus reference labels. Precision asks whether predicted labels were correct; recall asks how many reference instances were found.</caption><thead><tr><th>Theme</th><th>Support</th><th>Precision</th><th>Recall</th></tr></thead><tbody>{theme_rows}</tbody></table></div><p>Agreement was below the declared &gt;85% requirement, and three substantive themes lacked reference support or nonzero recall. This is a completed evaluation with a negative acceptance result. It demonstrates why interpreting campaign topics and measuring later communication are separate research tasks. The model’s residual rate must not be treated as evidence that the corresponding themes were absent from presidential communication.</p><p><a href="../data/trump/campaign/evaluation_report.json">Evaluation metrics and confusion counts</a> · Independent labels and final consensus (retained privately) · All 250 predictions (retained privately) · <a href="../data/trump/campaign/evaluation_execution_record.json">Execution verification and cost</a></p>'''
if d.get('demonstration_exception'):
    status='The principal investigator authorized an unvalidated demonstration with the unchanged classifier. The failed evaluation remains part of the evidence. Aggregate results are public; individual annotations and adjudication notes remain private.'
    evaluation+='<p>Individual annotations and post-level evaluation predictions are retained privately. Aggregate confusion counts and evidence hashes are released for inspection.</p><p><a href="../data/trump/campaign/demonstration_exception.json">Documented demonstration-only exception</a></p>'
    if d.get('prevalence'):
        status='The complete 26,239-post demonstration is available as unvalidated model-assigned shares. The classifier did not meet its held-out acceptance criteria. Individual annotation records remain private.'
        share_rows=''.join(f'<tr><td>{esc(row["theme"])}</td><td data-label="Posts">{int(row["documents"]):,}</td><td data-label="Share">{float(row["share"]):.2%}</td></tr>' for row in d['prevalence'])
        evaluation+=f'''<h2>What the unchanged model assigns.</h2><p>The author authorized a demonstration-only continuation after reviewing the failed evaluation. Every presidential post received an allowed label. These shares show the classifier’s assignments, including its measurement limitations; they are not validated estimates of the underlying themes.</p><div class="tutorial-table"><table class="evaluation-table shares-table"><caption>Unvalidated model-assigned shares. Denominator: all 26,239 presidential posting events, including retweets.</caption><thead><tr><th>Assigned category</th><th>Posts</th><th>Share</th></tr></thead><tbody>{share_rows}</tbody></table></div><p>Run <code>python scripts/check-published-metrics.py</code> in your checkout to independently verify the released aggregate arithmetic and evidence hashes, without private annotations or API calls.</p><p><a href="../data/trump/campaign/theme_counts.csv">Download aggregate counts</a> · <a href="../data/trump/campaign/estimand.json">Denominator and interpretation</a> · <a href="../data/trump/campaign/demonstration_verification.json">Full-corpus verification</a></p>'''
naming='The recorded run retains 500 completed naming votes per topic, including wording variation.' if d['naming_completed'] else 'Naming evidence is being collected for the adopted topics.'
result_summary=''
if d.get('evaluation_completed'):
    result_summary=f'''<div class="reproduction-callout"><h2>The result, before the details.</h2><p>Human theme review retained {len(d['topics'])} themes. The classifier matched {d['validation']['metrics']['agreement']:.0%} of the held-out human reference labels. It did not meet the declared acceptance criteria. Its separately authorized presidential assignments illustrate the workflow as <strong>unvalidated model-assigned shares</strong>.</p><p>Read downward to follow discovery, human interpretation, independent evaluation and the completed demonstration. A topic groups similar language; a theme gives that group a human-defined meaning.</p></div>'''
body=f'''<p class="eyebrow">Campaign discovery → presidential measurement</p><h1>See the evidence.<br>Follow the decisions.</h1><p class="lede">The example follows Donald Trump’s public Twitter posts from his campaign into his first presidency. It asks whether themes discovered in campaign language can be measured in later posts. This page records the answer and the evidence behind it. <a href="../data/">Meet the dataset first →</a></p><div class="cta"><a class="btn primary" href="../app/">Explore the walkthrough →</a><a class="btn" href="../data/trump/campaign-evidence.zip">Download campaign evidence</a></div>{result_summary}
<div class="design-flow"><article><span>DISCOVER</span><strong>7,805</strong><p>Campaign posts<br>June 16, 2015–November 8, 2016</p></article><article><span>HUMAN REVIEW</span><strong>The codebook</strong><p>Interpret themes. Independently annotate. Evaluate and accept the classifier.</p></article><article><span>MEASURE</span><strong>26,239</strong><p>Presidential posts<br>January 20, 2017–January 8, 2021</p></article></div>
<h2>A reviewed starting point for interpretation.</h2><p>The search evaluated 1,200 candidate settings. The researcher selected a 12-topic candidate after inspecting original-post evidence. Its c<sub>v</sub> coherence is {params['coherence']:.4f}; the fitted model's assignments were verified after reconstruction and reload.</p><div class="tutorial-metrics"><div class="tutorial-metric"><strong>{len(d['topics'])}</strong><span>campaign topics adopted</span></div><div class="tutorial-metric"><strong>{fmt(d['discovery_records'])}</strong><span>campaign posts modeled</span></div><div class="tutorial-metric"><strong>{100*d['outliers']/d['discovery_records']:.1f}%</strong><span>modeled posts unassigned</span></div></div>
<div class="tutorial-table"><table><caption>Adopted campaign topics. Proposed names remain interpretation aids.</caption><thead><tr><th>Topic</th><th>{'Modal LLM name' if d['naming_completed'] else 'Representative words'}</th><th>Posts</th></tr></thead><tbody>{topics}</tbody></table></div><p>{naming} Researchers read those proposals alongside posts and relevant literature; model consistency is not independent expert agreement.</p>
<h2>From statistical topics to human themes.</h2><p>Two-pass human theme review retained 12 distinct themes, with definitions and decision rules for their application to presidential language. This one-to-one map records the human interpretation; the software also allows several topics to share a theme. Approval of these meanings does not establish classification accuracy.</p><p><a href="../data/trump/campaign/codebook.json">Read the approved codebook</a> · <a href="../data/trump/campaign/human_synthesis_submission.json">Read the human review record</a> · <a href="../data/trump/campaign/theme_map.csv">Download the theme map</a></p><h2>Coverage matters as much as a score.</h2><p>Of the 7,805 campaign records, 7,779 retain modeled tokens and 26 are excluded from discovery after preprocessing. The adopted solution assigns 3,925 posts to topics and leaves 3,854 unassigned. Those unassigned posts remain part of the interpretive evidence. These discovery outcomes do not reduce the later presidential denominator.</p><p>The maximum-coherence solution placed 99.5% of its assigned posts in one broad cluster. The researcher selected a more differentiated candidate for interpretation. The numerical winner, every candidate and the explicit selection record remain preserved; the score was not silently substituted.</p>
{development}{evaluation}<h2>Different stages establish different things.</h2><div class="tutorial-table"><table><thead><tr><th>Evidence</th><th>What it establishes</th></tr></thead><tbody><tr><td>Campaign model and naming ballots</td><td>Computed groups and proposed descriptions of campaign language</td></tr><tr><td>Human synthesis</td><td>Researcher-defined meanings, boundaries and a frozen codebook</td></tr><tr><td>Development and held-out evaluation</td><td>Classifier selection followed by an independent assessment of its errors</td></tr><tr><td>Overall model-assigned shares</td><td>Recorded target assignments, including the residual; unvalidated in this demonstration</td></tr></tbody></table></div><p class="tutorial-note">{status} Visitor drafts and small live experiments demonstrate operations; they do not supply research approval.</p>
<h2>Reproduce the process in your own environment.</h2><p>The repository connects each decision to a maintained Python script and a retained artifact. Reviewers interpret; agents execute the documented steps. The demonstration reports overall model-assigned shares only, without period comparisons or causal claims. A fresh run may differ because probabilistic methods, model revisions and dependencies can change outputs.</p>
<details class="tutorial-note"><summary>Inspect the exact parameters and evidence</summary><div class="tutorial-table"><table><tbody><tr><th>Search</th><td>50 draws × ceilings 2–25; seed 42</td></tr><tr><th>Adopted draw / ceiling</th><td>{params['iteration']} / {params['max_topics']}</td></tr><tr><th>UMAP</th><td>{esc(json.dumps(params['umap_params']))}</td></tr><tr><th>HDBSCAN</th><td>{esc(json.dumps(params['hdbscan_params']))}</td></tr><tr><th>Embedding</th><td>all-MiniLM-L6-v2; pinned model revision in the run manifest</td></tr><tr><th>Discovery API calls</th><td>0</td></tr></tbody></table></div><p><a href="../data/trump/reference-run.json">Application record</a> · <a href="../data/trump/campaign/all_iteration_results.json">Every candidate</a> · <a href="../data/trump/campaign/selection_record.json">Model choice</a> · <a href="../data/trump/campaign/assignments.csv">Assignments</a> · <a href="../data/trump/campaign/excluded.csv">Preprocessing exclusions</a> · <a href="../data/trump/campaign/run_manifest.json">Environment and hashes</a> · <a href="../data/trump/campaign/artifact-integrity.json">Artifact checksums</a></p><figure><img src="../data/trump/campaign/coherence_curve.png" alt="Coherence across topic ceilings for the adopted campaign parameter draw" style="width:100%;height:auto"><figcaption>The requested ceiling and the number of observed topics are different quantities.</figcaption></figure></details>
<div class="evidence-links"><a href="../reproduce/">Fork + run</a><a href="../paper/">Standalone methods</a><a href="../data/README.md">Data and attribution</a><a href="../audit/">Original research library</a></div>'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Campaign application evidence — TopicLLM</title><meta name="description" content="Inspect the campaign topics, researcher decisions and independent validation behind TopicLLM's presidential prevalence application."><link rel="stylesheet" href="../site.css"><link rel="stylesheet" href="../reproduce.css"><link rel="stylesheet" href="../tutorial.css"></head><body><a class="skip" href="#main">Skip to evidence</a><main id="main" class="reproduce">{body}</main></body></html>'''
(root/'docs/validation/index.html').write_text(apply_shell(page),encoding='utf-8',newline='\n')
print('Built the campaign evidence page from recorded artifacts.')
